/** Identifier generation and validation. */

import crypto from 'node:crypto';

/**
 * New UUIDv4 for a primary key.
 *
 * Generated by the application rather than the database so a row's id is known
 * before the INSERT - which lets a single transaction write a record and the
 * audit entry that references it.
 */
export function newId(): string {
  return crypto.randomUUID();
}

const UUID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

/** True for a canonical RFC 4122 UUID (versions 1-5). */
export function isUuid(value: unknown): value is string {
  return typeof value === 'string' && UUID_PATTERN.test(value);
}

/**
 * Client-supplied device identifiers are only *mostly* UUIDs: an older
 * extension build may still send its own format. Accept a conservative
 * character set and length instead of rejecting the login outright.
 */
const CLIENT_ID_PATTERN = /^[A-Za-z0-9_-]{8,64}$/;

export function isValidClientDeviceId(value: unknown): value is string {
  return typeof value === 'string' && CLIENT_ID_PATTERN.test(value);
}
